import { cn } from '@/lib/utils';
import { format } from 'date-fns';
import { ar } from 'date-fns/locale';

export default function EntryExitSummaryCard({ className }: { className?: string }) {
    const now = new Date();
    const dayName = format(now, 'EEEE', { locale: ar });
    const fullDate = format(now, 'MMM d, yyyy', { locale: ar });

    return (
        <section
            className={cn(
                'mb-4 rounded-lg bg-primery-blue-500 p-4 text-white-blue-50 shadow-[0px_4px_12px_0px_#0C0C0D1A]',
                className,
            )}
        >
            <div className="mb-4 text-center">
                <p className="text-base font-semibold leading-6">{dayName}</p>
                <p className="text-xs text-primery-blue-100">{fullDate}</p>
            </div>

            <div className="mb-3 grid grid-cols-1 gap-3 md:grid-cols-2">
                <div className="rounded-md border border-primery-blue-400 bg-primery-blue-600 px-4 py-3 text-center">
                    <p className="mb-1 text-xs text-primery-blue-100">وقت البدء</p>
                    <p className="text-2xl font-semibold leading-8">00:00</p>
                </div>
                <div className="rounded-md border border-primery-blue-400 bg-primery-blue-600 px-4 py-3 text-center">
                    <p className="mb-1 text-xs text-primery-blue-100">وقت الانتهاء</p>
                    <p className="text-2xl font-semibold leading-8">00:00</p>
                </div>
            </div>

            <div className="grid grid-cols-3 rounded-md border border-primery-blue-400 bg-primery-blue-600 px-2 py-3 text-center">
                <div className="border-s border-primery-blue-400 px-2">
                    <p className="mb-1 text-xs text-primery-blue-100">الدخول</p>
                    <p className="text-sm">12:27 AM</p>
                </div>
                <div className="border-s border-primery-blue-400 px-2">
                    <p className="mb-1 text-xs text-primery-blue-100">الخروج</p>
                    <p className="text-sm">05:30 PM</p>
                </div>
                <div className="px-2">
                    <p className="mb-1 text-xs text-primery-blue-100">ساعات العمل</p>
                    <p className="text-sm">04:57 h</p>
                </div>
            </div>
        </section>
    );
}
